mapper.select:
SELECT r.*, i.item_name, i.unit, CASE WHEN r.remark LIKE '销售出库%' THEN '孙销售' ELSE COALESCE(u.real_name, r.operator) END AS operator_name, COALESCE(ou.real_name, pu.real_name, '张场长') AS auditor_name FROM biz_stock_record r LEFT JOIN biz_inventory i ON i.id = r.item_id AND i.deleted = 0 LEFT JOIN sys_user u ON u.username = r.operator LEFT JOIN biz_outbound bo ON r.remark = CONCAT('销售出库', bo.outbound_no) LEFT JOIN sys_user ou ON ou.username = bo.update_by LEFT JOIN biz_purchase bp ON r.remark = CONCAT('采购入库', bp.purchase_no) LEFT JOIN sys_user pu ON pu.username = bp.update_by WHERE 1 = 1
AND r.item_id = #{record.itemId}
AND r.biz_type = #{record.bizType}
ORDER BY r.create_time DESC, r.id DESC
